public String generateSessionId() {
        Random random = new Random();
        StringBuilder sessionId = new StringBuilder();

        // Generálj 16 karakteres véletlenszámot
        for (int i = 0; i < 16; i++) {
            int randomIndex = random.nextInt(62); // 0-61 közötti véletlenszám
            if (randomIndex < 10) {
                sessionId.append(randomIndex); // 0-9
            } else if (randomIndex < 36) {
                sessionId.append((char) ('A' + randomIndex - 10)); // A-Z
            } else {
                sessionId.append((char) ('a' + randomIndex - 36)); // a-z
            }
        }

        return sessionId.toString();
    }
}
