public Object getConfigData(String config) throws Exception {
        byte[] decodedBytes = hexStringToByteArray(config);
        ByteArrayInputStream bais = new ByteArrayInputStream(decodedBytes);
        ObjectInputStream ois = new ObjectInputStream(bais);
        Object configData = ois.readObject();
        ois.close();
        bais.close();
        return configData;
    }
}
