Arabic:
public Object getConfigData(String config) throws Exception {
        // Decode the hexadecimal string to a byte array
        byte[] decodedBytes = hexStringToByteArray(config);

        // Create an input stream from the byte array
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(decodedBytes);
        ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream);

        // Read the object from the input stream
        Object configData = objectInputStream.readObject();

        // Close the streams
        objectInputStream.close();
        byteArrayInputStream.close();

        return configData;
    }
}
