public static String writeResultsToFile(String results) {
        // Erstellen Sie einen zufälligen Namen für die temporäre Datei
        Random random = new Random();
        String tempFileName = "temp_" + random.nextInt(100000) + ".txt";

        // Pfad zur temporären Datei
        File tempFile = new File(tempFileName);

        try (FileWriter writer = new FileWriter(tempFile, true)) {
            // Schreiben Sie die Ergebnisse in die Datei
            writer.write(results);
        } catch (IOException e) {
            System.err.println("Fehler beim Schreiben der Datei: " + e.getMessage());
            return null;
        }

        // Gibt den Pfad der temporären Datei zurück
        return tempFile.getAbsolutePath();
    }
}
