    public static String generateFingerprint(String key, String iv) {
        try {
            // Create a SecretKeySpec from the key
            SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes(), "AES");

            // Create an IvParameterSpec from the iv
            IvParameterSpec ivParameterSpec = new IvParameterSpec(iv.getBytes());

            // Create a Cipher instance for AES in CBC mode
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");

            // Initialize the cipher with the secret key and iv
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

            // Encrypt a dummy byte array to get the fingerprint
            byte[] dummyData = new byte[16];
            byte[] encryptedData = cipher.doFinal(dummyData);

            // Convert the encrypted data to a hexadecimal string
            StringBuilder fingerprint = new StringBuilder();
            for (byte b : encryptedData) {
                fingerprint.append(String.format("%02x", b));
            }

            return fingerprint.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error generating fingerprint", e);
        }
    }
