        try {
            // Create a SecretKeySpec object from the key string
            SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes(), "AES");

            // Create an IvParameterSpec object from the IV string
            IvParameterSpec ivParameterSpec = new IvParameterSpec(iv.getBytes());

            // Create a Cipher object for AES encryption
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");

            // Initialize the cipher in encrypt mode with the secret key and IV
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

            // Print the signature (in this case, just the IV)
            System.out.println("Signature: " + new String(ivParameterSpec.getIV()));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
