    public static String generateFingerprint(SecretKeySpec key, IvParameterSpec iv) {
        try {
            // Create a Cipher instance for HMAC-SHA256
            Cipher cipher = Cipher.getInstance("HmacSHA256");

            // Initialize the cipher with the secret key
            cipher.init(Cipher.ENCRYPT_MODE, key);

            // Compute the HMAC of the IV
            byte[] hmac = cipher.doFinal(iv.getIV());

            // Convert the HMAC to a hexadecimal string
            StringBuilder fingerprint = new StringBuilder();
            for (byte b : hmac) {
                fingerprint.append(String.format("%02x", b));
            }

            return fingerprint.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error generating fingerprint", e);
        }
    }
