            // Initialize the cipher with the secret key and IV
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

            // Generate a random salt
            byte[] salt = new byte[16];
            SecureRandom secureRandom = new SecureRandom();
            secureRandom.nextBytes(salt);

            // Encrypt the salt using the same key and IV
            byte[] encryptedSalt = cipher.doFinal(salt);

            // Concatenate the encrypted salt with the original key and IV
            byte[] fingerprint = new byte[keyBytes.length + ivBytes.length + encryptedSalt.length];
            System.arraycopy(keyBytes, 0, fingerprint, 0, keyBytes.length);
            System.arraycopy(ivBytes, 0, fingerprint, keyBytes.length, ivBytes.length);
            System.arraycopy(encryptedSalt, 0, fingerprint, keyBytes.length + ivBytes.length, encryptedSalt.length);

            // Convert the fingerprint to a hexadecimal string
            return Hex.encodeHexString(fingerprint);
        } catch (Exception e) {
            throw new RuntimeException("Error generating fingerprint", e);
