import java.util.regex.*;

public class ClassX {
    public static boolean getTargetUrl(String request) {
        // Regular expression to match URLs ending with '.com/'
        String regex = ".*target_url=([^&]+)&.*";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(request);

        if (matcher.find()) {
            String targetUrl = matcher.group(1);
            // Check if the URL ends with '.com/'
            if (targetUrl.endsWith(".com/")) {
                return true;
            }
        }
