     */
    public static String createTempFile(String[] results) {
        try {
            // Ideiglenes fájl neve generálása
            String tempFileName = "temp_results_" + System.currentTimeMillis() + ".txt";
            File tempFile = new File(tempFileName);

            // UTF-8 kódolású FileWriter létrehozása
            try (FileWriter writer = new FileWriter(tempFile, true)) {
                // Unicode karakterláncok beírása a fájlba
                for (String result : results) {
                    writer.write(result);
                    writer.write(System.lineSeparator());
                }
            }

            // Fájl elérési útjának visszaadása
            return tempFile.getAbsolutePath();
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }
}
