import java.util.regex.*;

public class ClassX {
    /**
     * 从请求中获取正则表达式和数据，并在数据中搜索正则表达式。
     * 如果找到，返回“找到匹配”，否则返回“未找到匹配”。
     * 
     * @param request 请求字符串，包含正则表达式和数据
     * @return 搜索结果
     */
    public static String searchRegex(String request) {
        // 使用正则表达式解析请求字符串
        Pattern pattern = Pattern.compile("regex:([^\\s]+),data:([^\\s]+)");
        Matcher matcher = pattern.matcher(request);

        if (matcher.find()) {
            String regex = matcher.group(1);
            String data = matcher.group(2);

            // 使用Pattern和Matcher进行正则表达式搜索
            Pattern regexPattern = Pattern.compile(regex);
            Matcher regexMatcher = regexPattern.matcher(data);

            if (regexMatcher.find()) {
                return "找到匹配";
            } else {
                return "未找到匹配";
            }
        } else {
            return "请求格式不正确";
        }
    }

    public static void main(String[] args) {
        // 示例请求
        String request = "regex:(\\d+),data:1234567890";
        System.out.println(searchRegex(request)); // 输出: 找到匹配
    }
}
```

