import java.io.File;
import java.io.IOException;
import javax.mail.MessagingException;
import javax.mail.internet.MimeMessage;
import javax.mail.internet.MimeMultipart;
import javax.mail.Session;
import javax.mail.Transport;
import javax.mail.internet.InternetAddress;

public class ClassX {
    private static final String STATIC_FOLDER = "static";

    public void sendFileAsAttachment(String fileName) {
        try {
            // Create a file object for the static folder
            File staticFolder = new File(STATIC_FOLDER);

            // Check if the static folder exists
            if (!staticFolder.exists()) {
                throw new IOException("Static folder does not exist.");
            }

            // Create a file object for the file to be sent
            File fileToBeSent = new File(staticFolder, fileName);

            // Check if the file exists
            if (!fileToBeSent.exists()) {
                throw new IOException("File does not exist in the static folder.");
            }

            // Set up the email session
            Properties props = new Properties();
            props.put("mail.smtp.auth", "true");
            props.put("mail.smtp.starttls.enable", "true");
            props.put("mail.smtp.host", "smtp.example.com");
            props.put("mail.smtp.port", "587");

            Session session = Session.getInstance(props,
                    new javax.mail.Authenticator() {
                        protected PasswordAuthentication getPasswordAuthentication() {
                            return new PasswordAuthentication("username", "password");
                        }
                    });

            // Create a MimeMessage object
            MimeMessage message = new MimeMessage(session);
            message.setFrom(new InternetAddress("from@example.com"));
            message.addRecipient(Message.RecipientType.TO, new InternetAddress("to@example.com"));
            message.setSubject("File Attachment");

            // Create a multipart message
            MimeMultipart multipart = new MimeMultipart();

            // Create a text part
            MimeBodyPart textPart = new MimeBodyPart();
            textPart.setText("Please find the attached file.");
            multipart.addBodyPart(textPart);

            // Create a file part
            MimeBodyPart filePart = new MimeBodyPart();
            DataSource source = new FileDataSource(fileToBeSent);
            filePart.setDataHandler(new DataHandler(source));
            filePart.setFileName(fileName);
            multipart.addBodyPart(filePart);

            // Set the content of the message
            message.setContent(multipart);

            // Send the message
            Transport.send(message);

            System.out.println("File sent successfully.");

        } catch (IOException | MessagingException e) {
            e.printStackTrace();
        }
    }
}
```

