public static Document parseXML(String file_path) {
        try {
            // I-create ang DocumentBuilderFactory
            DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
            // I-create ang DocumentBuilder
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
            // I-load ang XML file
            Document doc = dBuilder.parse(new File(file_path));
            // I-normalize ang document
            doc.getDocumentElement().normalize();
            // I-return ang root element
            return doc.getDocumentElement();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
