public static org.w3c.dom.Element parseXML(String file_path) {
        try {
            // Maak een DocumentBuilderFactory
            DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();

            // Maak een DocumentBuilder
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();

            // Parse het XML-bestand
            Document doc = dBuilder.parse(new File(file_path));

            // Verwijder de whitespace tussen elementen
            doc.getDocumentElement().normalize();

            // Retourneer het root-element
            return doc.getDocumentElement();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
