    public static String encryptData(String data, String key) throws Exception {
        // Convert the key from Base64 to bytes
        byte[] keyBytes = Base64.getDecoder().decode(key);

        // Create a SecretKeySpec object from the key bytes
        SecretKeySpec secretKeySpec = new SecretKeySpec(keyBytes, "AES");

        // Create an IvParameterSpec object for the initialization vector (IV)
        IvParameterSpec ivParameterSpec = new IvParameterSpec(new byte[16]); // AES block size is 16 bytes

        // Create a Cipher object for AES in CBC mode with PKCS5Padding
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

        // Pad the data to the block size
        int blockSize = cipher.getBlockSize();
        int paddingLength = blockSize - (data.length() % blockSize);
        byte[] paddedData = new byte[data.length() + paddingLength];
        System.arraycopy(data.getBytes(), 0, paddedData, 0, data.length());
        for (int i = data.length(); i < paddedData.length; i++) {
            paddedData[i] = (byte) paddingLength;
        }

        // Encrypt the padded data
        byte[] encryptedData = cipher.doFinal(paddedData);

        // Convert the encrypted data to Base64
        return Base64.getEncoder().encodeToString(encryptedData);
    }
}
```

