public byte[] readBytes(int num_bytes) throws IOException {
            byte[] buffer = new byte[num_bytes];
            int bytesRead = _stream.read(buffer);
            if (bytesRead < num_bytes) {
                throw new EOFError("Not enough bytes available in the input stream.");
            }
            return buffer;
        }
    }
}
