public byte[] readBytes(int num_bytes) throws IOException {
            byte[] buffer = new byte[num_bytes];
            int bytesRead = 0;

            while (bytesRead < num_bytes) {
                int read = _stream.read(buffer, bytesRead, num_bytes - bytesRead);
                if (read == -1) {
                    throw new EOFError("End of file reached before reading enough bytes.");
                }
                bytesRead += read;
            }

            return buffer;
        }
    }
}
