import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Erhalten Sie den inputStr als Python-Ausdruck aus der Anfrage unter Verwendung von 'inputStr'. Geben Sie das Ergebnis des berechneten Ausdrucks zurück.
     */
    public static Object evaluatePythonExpression(String inputStr) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("python");

        try {
            return engine.eval(inputStr);
        } catch (ScriptException e) {
            System.err.println("Fehler beim Evaluieren des Python-Ausdrucks: " + e.getMessage());
            return null;
        }
    }

    public static void main(String[] args) {
        String inputStr = "2 + 3 * 4";
        Object result = evaluatePythonExpression(inputStr);
        if (result!= null) {
            System.out.println("Das Ergebnis des Python-Ausdrucks ist: " + result);
        }
    }
}
