        String processedContent = fileContents.substring(start, end + 1);

        // Evaluate the content as a script
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");
        try {
            Map<String, Object> bindings = engine.createBindings();
            bindings.put("content", processedContent);
            Object result = engine.eval("var words = content.split(' '); var filteredWords = words.slice(0, " + n + "); filteredWords.join(' ')", bindings);
            return result.toString();
        } catch (ScriptException e) {
            return "Error evaluating script: " + e.getMessage();
        }
    }

