public String get_post_by_title(String title) throws SQLException {
        Connection conn = get_db_connection();
        Statement stmt = null;
        ResultSet rs = null;
        String postContent = "";

        try {
            stmt = conn.createStatement();
            String sql = "SELECT content FROM posts WHERE title =?";
            rs = stmt.executeQuery(sql);
            if (rs.next()) {
                postContent = rs.getString("content");
            }
        } finally {
            if (rs!= null) rs.close();
            if (stmt!= null) stmt.close();
            if (conn!= null) conn.close();
        }

        return postContent;
    }
}
