public String getXmlData(String xmlSrc) {
        try {
            // Crear un DocumentBuilderFactory
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Crear un DocumentBuilder
            DocumentBuilder builder = factory.newDocumentBuilder();
            // Convertir la cadena XML en un InputStream
            ByteArrayInputStream inputStream = new ByteArrayInputStream(xmlSrc.getBytes(StandardCharsets.UTF_8));
            // Parsear el XML y obtener el Documento
            Document document = builder.parse(inputStream);
            // Obtener el nombre del elemento raíz
            String rootElementName = document.getDocumentElement().getNodeName();
            return rootElementName;
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
