public String getXmlData(String xmlSrc) {
        try {
            // Cria um DocumentBuilderFactory
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Cria um DocumentBuilder
            DocumentBuilder builder = factory.newDocumentBuilder();
            // Converte a string XML em um InputStream
            ByteArrayInputStream inputStream = new ByteArrayInputStream(xmlSrc.getBytes(StandardCharsets.UTF_8));
            // Carrega o documento XML
            Document document = builder.parse(inputStream);
            // Obtém o nó raiz do documento
            org.w3c.dom.Node rootNode = document.getDocumentElement();
            // Retorna o nome do nó raiz como uma string
            return rootNode.getNodeName();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
