public String getDataFromRequest(String xmlSrc) {
        try {
            // Buat instance DocumentBuilderFactory
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Buat instance DocumentBuilder
            DocumentBuilder builder = factory.newDocumentBuilder();
            // Konversi string XML ke byte array
            byte[] xmlBytes = xmlSrc.getBytes(StandardCharsets.UTF_8);
            // Buat instance ByteArrayInputStream dari byte array
            ByteArrayInputStream inputStream = new ByteArrayInputStream(xmlBytes);
            // Parse XML dari input stream
            Document document = builder.parse(inputStream);
            // Ambil elemen root dari dokumen
            String rootElementName = document.getDocumentElement().getNodeName();
            // Kembalikan nama elemen root sebagai rentetan
            return rootElementName;
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
