public static String parseXml(String xmlSrc) {
        try {
            // Erstellen Sie ein DocumentBuilderFactory-Objekt
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Erstellen Sie ein DocumentBuilder-Objekt
            DocumentBuilder builder = factory.newDocumentBuilder();
            // Erstellen Sie ein ByteArrayInputStream-Objekt aus dem XML-String
            ByteArrayInputStream inputStream = new ByteArrayInputStream(xmlSrc.getBytes(StandardCharsets.UTF_8));
            // Parsen Sie das XML und erhalten Sie das Document-Objekt
            Document document = builder.parse(inputStream);
            // Setzen Sie den Dokumentenparser auf Strict-Modus
            document.getDocumentElement().normalize();
            // Konvertieren Sie das Document-Objekt in einen String
            return document.getDocumentElement().getNodeName();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
