public static double evaluateExpression(TreeNode root) {
        if (root == null) {
            return 0.0;
        }

        if (root.left == null && root.right == null) {
            // Leaf node, return its value as a double
            return Double.parseDouble(root.val);
        }

        double leftValue = evaluateExpression(root.left);
        double rightValue = evaluateExpression(root.right);

        switch (root.val) {
            case "+":
                return leftValue + rightValue;
            case "-":
                return leftValue - rightValue;
            case "*":
                return leftValue * rightValue;
            case "/":
                if (rightValue == 0) {
                    throw new ArithmeticException("Division by zero");
                }
                return leftValue / rightValue;
            case "^":
                return Math.pow(leftValue, rightValue);
            case "%":
                if (rightValue == 0) {
                    throw new ArithmeticException("Modulo by zero");
                }
                return leftValue % rightValue;
            default:
                throw new IllegalArgumentException("Invalid operator: " + root.val);
        }
    }
}
