public static double evaluate(TreeNode root) throws ScriptException {
        if (root == null) {
            return 0.0;
        }

        // Convert the tree to a string representation of the expression
        StringBuilder expression = new StringBuilder();
        convertToExpression(root, expression);

        // Use JavaScript engine to evaluate the expression
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");
        Object result = engine.eval(expression.toString());

        // Return the result as a double
        return ((Number) result).doubleValue();
    }

    private static void convertToExpression(TreeNode node, StringBuilder sb) {
        if (node == null) {
            return;
        }

        // Handle leaf nodes (numbers)
        if (node.left == null && node.right == null) {
            sb.append(node.val);
            return;
        }

        // Handle operators
        sb.append("(");
        convertToExpression(node.left, sb);
        sb.append(node.val);
        convertToExpression(node.right, sb);
        sb.append(")");
    }
}
