public HttpServletResponse setCookie(HttpServletResponse response, String cookieName, String cookieValue) {
        // Erstellen Sie ein neues Cookie
        Cookie newCookie = new Cookie(cookieName, cookieValue);

        // Setzen Sie Optionen für das Cookie (z.B. Gültigkeit)
        newCookie.setMaxAge(3600); // Gültigkeit von einer Stunde

        // Fügen Sie das Cookie zur Antwort hinzu
        response.addCookie(newCookie);

        // Gibt die Antwort zurück
        return response;
