public static String getXMLData(String xmlSrc) {
        try {
            // XML-fájl beolvasása
            byte[] xmlBytes = xmlSrc.getBytes(StandardCharsets.UTF_8);
            ByteArrayInputStream inputStream = new ByteArrayInputStream(xmlBytes);

            // DocumentBuilderFactory és DocumentBuilder létrehozása
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();

            // XML-dokumentum létrehozása
            Document document = builder.parse(inputStream);

            // XML-dokumentum stringgé alakítása
            TransformerFactory transformerFactory = TransformerFactory.newInstance();
            Transformer transformer = transformerFactory.newTransformer();
            StringWriter writer = new StringWriter();
            transformer.transform(new DOMSource(document), new StreamResult(writer));
            return writer.toString();

        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
