            return "Error: Missing XML in request";
        }

        // Parse the XPath from the request
        String xslt = extractValue(request, "xslt");
        if (xslt == null) {
            return "Error: Missing XSLT in request";
        }

        try {
            // Create a TransformerFactory instance
            TransformerFactory transformerFactory = TransformerFactory.newInstance();

            // Create a Transformer instance
            Transformer transformer = transformerFactory.newTransformer(new StreamSource(new StringReader(xslt)));

            // Create a StringWriter to capture the result
            StringWriter writer = new StringWriter();
            StreamResult result = new StreamResult(writer);

            // Transform the XML using the XSLT
            transformer.transform(new StreamSource(new StringReader(xml)), result);

            // Return the transformed XML as a string
            return writer.toString();
        } catch (Exception e) {
            return "Error processing request: " + e.getMessage();
        }
    }

    private String extractValue(String request, String key) {
        // Split the request into key-value pairs
        String[] parts = request.split("&");
        for (String part : parts) {
            // Split each part into key and value
            String[] keyValue = part.split("=");
            if (keyValue.length == 2 && keyValue[0].equals(key)) {
                return keyValue[1];
            }
        }
        return null;
    }
}
