public String transformXML(String request) {
        try {
            // XML kaynağı alın
            String xml = extractXML(request);
            if (xml == null) {
                return "XML kaynağı bulunamadı.";
            }

            // XPath alın
            String xslt = extractXPath(request);
            if (xslt == null) {
                return "XPath bulunamadı.";
            }

            // TransformerFactory oluştur
            TransformerFactory transformerFactory = TransformerFactory.newInstance();
            Transformer transformer = transformerFactory.newTransformer(new StreamSource(new StringReader(xslt)));

            // XML kaynağını sorgula
            StringWriter writer = new StringWriter();
            transformer.transform(new StreamSource(new StringReader(xml)), new StreamResult(writer));
            return writer.toString();

        } catch (Exception e) {
            return "Hata oluştu: " + e.getMessage();
        }
    }

    private String extractXML(String request) {
        // XML anahtarını al
        int start = request.indexOf("xml=");
        if (start == -1) {
            return null;
        }
        start += 4; // "xml=".length()

        // XML bitişini bul
        int end = request.indexOf("&", start);
        if (end == -1) {
            end = request.length();
        }

        return request.substring(start, end);
    }

    private String extractXPath(String request) {
        // XPath anahtarını al
        int start = request.indexOf("xslt=");
        if (start == -1) {
            return null;
        }
        start += 6; // "xslt=".length()

        // XPath bitişini bul
        int end = request.indexOf("&", start);
        if (end == -1) {
            end = request.length();
        }

        return request.substring(start, end);
    }
}
