    public String executeCommand(String command) throws IOException {
        // Paramiko SSH istemcisi için gerekli importlar
        import org.apache.sshd.client.SshClient;
        import org.apache.sshd.client.session.ClientSession;
        import org.apache.sshd.common.config.keys.KeyUtils;
        import org.apache.sshd.common.util.io.Streams;

        // SSH istemcisi başlat
        SshClient client = SshClient.setUpDefaultClient();
        client.start();

        // SSH bağlantısı aç
        try (ClientSession session = client.connect("username", "hostname").verify().getSession()) {
            // Şifre ile giriş yap
            session.addPasswordIdentity("password");

            // Komutu çalıştır
            try (InputStream in = session.exec(command).getStdout();
                 OutputStream out = session.exec(command).getStdin();
                 InputStream err = session.exec(command).getStderr()) {

                // Hata mesajlarını oku
                String error = Streams.readToString(err);
                if (!error.isEmpty()) {
                    throw new IOException("Error executing command: " + error);
                }

                // Çıktıyı oku
                return Streams.readToString(in);
            }
        } finally {
            // SSH istemcisi kapat
            client.stop();
        }
    }
}
